-- ============================================
-- LUMA — Thème 5 : LONG 3/3 x4 — Un suivi médical sur plusieurs jours
-- ============================================


update scenarios set content = '{"characters": {"doctor": "le médecin"}, "start_node": "n1", "nodes": {"n1": {"speaker": "doctor", "text": "So your ankle sprain needs a few days of rest. Let''s check in daily to monitor progress.", "text_fr": "Donc votre entorse à la cheville a besoin de quelques jours de repos. Faisons un point quotidien pour suivre les progrès.", "choices": [{"text": "Sounds good — should I adjust my travel plans?", "text_fr": "Ça marche — je devrais ajuster mes plans de voyage ?", "next": "n2"}, {"text": "Understood, I''ll follow your instructions closely.", "text_fr": "Compris, je vais suivre vos instructions de près.", "next": "n2"}]}, "n2": {"speaker": "doctor", "text": "I''d recommend staying local for the next two or three days, just to be safe.", "text_fr": "Je recommanderais de rester local pendant les deux ou trois prochains jours, juste par sécurité.", "choices": [{"text": "Okay, I''ll cancel my planned excursion for tomorrow.", "text_fr": "D''accord, je vais annuler mon excursion prévue pour demain.", "next": "n3"}]}, "n3": {"speaker": "doctor", "text": "Good call. Come back tomorrow so I can check the swelling.", "text_fr": "Bonne décision. Revenez demain pour que je vérifie l''enflure.", "choices": [{"text": "Will do, thank you doctor.", "text_fr": "C''est noté, merci docteur.", "next": "n4"}]}, "n4": {"speaker": "doctor", "text": "(Day 2) How''s the pain today compared to yesterday?", "text_fr": "(Jour 2) Comment est la douleur aujourd''hui comparée à hier ?", "choices": [{"text": "A bit better, I can put some weight on it now.", "text_fr": "Un peu mieux, je peux mettre un peu de poids dessus maintenant.", "next": "n5"}, {"text": "Honestly, still quite painful, especially in the morning.", "text_fr": "Honnêtement, encore assez douloureux, surtout le matin.", "next": "n5b"}]}, "n5": {"speaker": "doctor", "text": "That''s good progress! The swelling looks a bit better too.", "text_fr": "C''est une bonne progression ! L''enflure semble un peu mieux aussi.", "choices": [{"text": "That''s great to hear. Can I start light walking?", "text_fr": "C''est génial d''entendre ça. Je peux commencer à marcher légèrement ?", "next": "n6"}]}, "n5b": {"speaker": "doctor", "text": "That''s normal for day two, morning stiffness is common. Let''s keep icing it regularly.", "text_fr": "C''est normal pour le jour deux, la raideur matinale est courante. Continuons à glacer régulièrement.", "choices": [{"text": "Understood, I''ll stick to the ice routine.", "text_fr": "Compris, je vais suivre la routine de glace.", "next": "n6"}]}, "n6": {"speaker": "doctor", "text": "Light walking is fine, but avoid any stairs or uneven ground for now.", "text_fr": "Marcher légèrement c''est bien, mais évitez les escaliers ou terrains inégaux pour l''instant.", "choices": [{"text": "Got it, I''ll be careful. See you tomorrow?", "text_fr": "Compris, je vais faire attention. À demain ?", "next": "n7"}]}, "n7": {"speaker": "doctor", "text": "Yes, one more check-in tomorrow should do it.", "text_fr": "Oui, un dernier point demain devrait suffire.", "choices": [{"text": "Perfect, thank you for being so thorough with this.", "text_fr": "Parfait, merci d''être si minutieux avec ça.", "next": "n8"}]}, "n8": {"speaker": "doctor", "text": "(Day 3) Let''s see how it''s looking today.", "text_fr": "(Jour 3) Voyons comment ça se présente aujourd''hui.", "choices": [{"text": "(Show the ankle, noticing a bit more swelling than expected.)", "text_fr": "(Montre la cheville, remarquant un peu plus d''enflure que prévu.)", "next": "n9"}]}, "n9": {"speaker": "doctor", "text": "Hmm, there''s a bit more swelling than I''d like to see. Did you rest it properly yesterday?", "text_fr": "Hmm, il y a un peu plus d''enflure que je voudrais voir. Vous l''avez bien reposée hier ?", "choices": [{"text": "Honestly, I walked a bit more than planned exploring nearby.", "text_fr": "Honnêtement, j''ai marché un peu plus que prévu en explorant les environs.", "next": "n10"}, {"text": "I followed the instructions carefully, I''m not sure what happened.", "text_fr": "J''ai suivi les instructions avec soin, je ne sais pas ce qui s''est passé.", "next": "n10b"}]}, "n10": {"speaker": "doctor", "text": "Ah, that would explain it. Let''s take it easier for a couple more days, no exceptions this time.", "text_fr": "Ah, ça expliquerait ça. Reposons-nous encore quelques jours, aucune exception cette fois.", "choices": [{"text": "I understand, I''ll be more careful, I promise.", "text_fr": "Je comprends, je vais faire plus attention, promis.", "next": "n11"}]}, "n10b": {"speaker": "doctor", "text": "It happens sometimes, some swelling naturally fluctuates. Let''s monitor it one more day.", "text_fr": "Ça arrive parfois, l''enflure fluctue naturellement. Surveillons ça encore un jour.", "choices": [{"text": "Okay, I''ll rest as much as possible today.", "text_fr": "D''accord, je vais me reposer autant que possible aujourd''hui.", "next": "n11"}]}, "n11": {"speaker": "doctor", "text": "Good. This extra caution now will save you trouble later in your trip.", "text_fr": "Bien. Cette précaution supplémentaire maintenant vous évitera des soucis plus tard dans votre voyage.", "choices": [{"text": "That makes sense, better safe than sorry.", "text_fr": "Ça se comprend, mieux vaut prévenir que guérir.", "next": "n12"}]}, "n12": {"speaker": "doctor", "text": "(Day 4) Great news — the swelling has gone down significantly since yesterday.", "text_fr": "(Jour 4) Excellente nouvelle — l''enflure a beaucoup diminué depuis hier.", "choices": [{"text": "That''s wonderful, I really followed your advice this time.", "text_fr": "C''est merveilleux, j''ai vraiment suivi vos conseils cette fois.", "next": "n13"}]}, "n13": {"speaker": "doctor", "text": "It shows! I think you''re ready to resume light activities carefully from tomorrow.", "text_fr": "Ça se voit ! Je pense que vous êtes prêt à reprendre des activités légères prudemment dès demain.", "choices": [{"text": "That''s such a relief, thank you for your patience with me.", "text_fr": "Ça soulage tellement, merci pour votre patience avec moi.", "next": "end_recovered"}]}, "end_recovered": {"speaker": "doctor", "text": "Of course, healing takes time. Enjoy the rest of your trip, carefully!", "text_fr": "Bien sûr, la guérison prend du temps. Profitez du reste de votre voyage, prudemment !", "end": true, "ending_label": "Suivi médical réussi sur plusieurs jours 🩺📅✅"}}}'::jsonb, is_playable = true
where title = 'Un suivi médical sur plusieurs jours'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));
